const body = $('Webhook — Missão Semanal').first().json.body ||
             $('Webhook — Missão Semanal').first().json;
const { nicho, cidades, meta_semanal = 150 } = body;
if (!nicho?.trim()) throw new Error('Payload inválido: "nicho" é obrigatório.');
if (!cidades)       throw new Error('Payload inválido: "cidades" é obrigatório.');
const cidadesArr = Array.isArray(cidades) ? cidades : [cidades];
if (cidadesArr.length === 0) throw new Error('Pelo menos uma cidade é obrigatória.');
const lote_diario = Math.ceil(meta_semanal / 7);
const candidatos_meta = lote_diario * 3;
const serp_queries = cidadesArr.map(c => `site:instagram.com "${nicho}" "${c}"`).join('
');
const serp_paginas = Math.min(Math.max(1, Math.ceil(candidatos_meta / (10 * cidadesArr.length))), 5);
$workflow.staticData.missao = {
  nicho, cidades: cidadesArr, meta_semanal, lote_diario, candidatos_meta,
  inicio: new Date().toISOString()
};
return [{ json: {
  nicho, cidades: cidadesArr, lote_diario, candidatos_meta,
  serp_queries, serp_paginas,
  search_query_fallback: `${nicho} ${cidadesArr[0]}`
} }];

const serpItems = $input.all();
const redisRaw = $('Redis — GET Blacklist Cache').first().json.value || '[]';
const blacklist = JSON.parse(redisRaw).map(u => u.toLowerCase().trim());
const missao = $workflow.staticData.missao || {};
const CONCORRENTE_KW = ['design','designer','criativo','criativa','logo','branding',
  'agência','agencia','marketing','identidade visual','portfólio','portfolio'];
const IG_URL_RE = /instagram\.com\/([a-z0-9_\.]{1,30})(?:\/|\?|$)/i;
const IG_RESERVADOS = new Set(['p','stories','reels','explore','accounts','tv','reel']);
const candidatos = [];
const descartados_serp = { blacklist: 0, concorrente: 0, url_invalida: 0, duplicado: 0 };
const seen = new Set();
for (const item of serpItems) {
  const results = Array.isArray(item.json) ? item.json : [item.json];
  for (const r of results) {
    const url = r.url || r.link || '';
    if (!url) continue;
    const match = IG_URL_RE.exec(url);
    if (!match) { descartados_serp.url_invalida++; continue; }
    const username = match[1].toLowerCase().trim();
    if (IG_RESERVADOS.has(username)) { descartados_serp.url_invalida++; continue; }
    if (seen.has(username)) { descartados_serp.duplicado++; continue; }
    seen.add(username);
    if (blacklist.includes(username)) { descartados_serp.blacklist++; continue; }
    const texto = `${r.title || ''} ${r.description || r.snippet || ''}`.toLowerCase();
    if (CONCORRENTE_KW.some(kw => texto.includes(kw))) { descartados_serp.concorrente++; continue; }
    const cidades = missao.cidades || [];
    const cidade_detectada = cidades.find(c => texto.includes(c.toLowerCase())) || cidades[0] || '';
    candidatos.push({ username, cidade: cidade_detectada });
  }
}
console.log(`[SDR SERP] Candidatos: ${candidatos.length} | Descartados:`, JSON.stringify(descartados_serp));
const lote_diario = missao.lote_diario || 22;
const tem_suficientes = candidatos.length >= lote_diario;
return [{ json: {
  candidatos,
  usernames: candidatos.map(c => c.username),
  tem_suficientes,
  total_candidatos: candidatos.length,
  lote_diario,
  descartados_serp,
  nicho: missao.nicho || '',
  cidades: missao.cidades || [],
  search_query_fallback: `${missao.nicho || ''} ${(missao.cidades || [])[0] || ''}`
} }];

const apifyItems = $input.all();
const missao = $workflow.staticData.missao || {};
const serpData = $('Code — Extrai Usernames + Pré-Filtro').first().json;
const cidadeMap = {};
(serpData.candidatos || []).forEach(c => {
  if (c.username) cidadeMap[c.username.toLowerCase()] = c.cidade;
});
const CONCORRENTE_KW = ['design','designer','criativo','criativa','arte','artista',
  'portfolio','portfólio','branding','logo','logotipo','agência','agencia',
  'marketing','identidade visual','marca','social media','tráfego','gestor','gestora'];
const qualificados = [];
const descartados = { nao_b2b: 0, concorrente: 0, inativo: 0, score_baixo: 0 };
for (const item of apifyItems) {
  const profiles = Array.isArray(item.json) ? item.json : [item.json];
  for (const p of profiles) {
    if (!p || !p.username) continue;
    const username = (p.username || '').toLowerCase().trim();
    const is_business = p.isBusinessAccount === true;
    const bio         = (p.biography || '').toLowerCase();
    const ext_url     = (p.externalUrl || '').toLowerCase().trim();
    const followers   = Number(p.followersCount) || 0;
    const pic_url     = p.profilePicUrlHD || p.profilePicUrl || '';
    const latestPosts = p.latestPosts || [];
    const latestTs    = latestPosts.length > 0
      ? (latestPosts[0].timestamp || latestPosts[0].takenAtTimestamp || null)
      : null;
    if (!is_business && !ext_url) { descartados.nao_b2b++; continue; }
    if (CONCORRENTE_KW.some(kw => bio.includes(kw))) { descartados.concorrente++; continue; }
    let score = 0;
    if      (followers >= 1000  && followers <= 15000) score += 20;
    else if (followers > 15000  && followers <= 50000) score += 10;
    if (latestTs) {
      const postDate  = new Date(typeof latestTs === 'number' ? latestTs * 1000 : latestTs);
      const daysSince = (Date.now() - postDate.getTime()) / 86400000;
      if (daysSince > 30)  { descartados.inativo++; continue; }
      if (daysSince <= 7)  score += 15;
      else if (daysSince <= 14) score += 10;
    }
    const isAmateur = !ext_url
      || ext_url.includes('linktr.ee')
      || ext_url.includes('beacons.ai')
      || ext_url.includes('bio.site')
      || ext_url.includes('wa.me')
      || ext_url.includes('api.whatsapp');
    if (isAmateur)   score += 15;
    if (is_business) score += 10;
    if (score < 40) { descartados.score_baixo++; continue; }
    const cidade = cidadeMap[username] || (missao.cidades ? missao.cidades[0] : '');
    qualificados.push({ json: {
      Username:        p.username,
      Nome_Empresa:    p.fullName || p.username,
      Bio:             p.biography || '',
      Link_IG:         `https://www.instagram.com/${p.username}/`,
      External_URL:    p.externalUrl || '',
      Lead_Score:      score,
      Followers:       followers,
      Status:          'Curadoria',
      Foto_Perfil_URL: pic_url,
      Data_Entrada:    new Date().toISOString(),
      Nicho:           missao.nicho  || '',
      Cidade:          cidade,
      is_business:     is_business
    } });
  }
}
console.log(`[SDR Score] Qualificados: ${qualificados.length} | Descartados:`, JSON.stringify(descartados));
$workflow.staticData.ultima_mineracao = {
  qualificados: qualificados.length, descartados, timestamp: new Date().toISOString()
};
if (qualificados.length === 0) return [{ json: { _sem_leads: true, total: 0, descartados } }];
return qualificados;

